import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int[][] grid = new int[n][m];
        Map<Integer, List<int[]>> positions = new HashMap<>();

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < m; j++) {
                int val = Integer.parseInt(st.nextToken());
                grid[i][j] = val;
                if (!positions.containsKey(val)) {
                    positions.put(val, new ArrayList<>());
                }
                positions.get(val).add(new int[]{i, j});
            }
        }

        // For each pair, we need to check if the two shoes are adjacent.
        // If they are not adjacent, we need to move at least one shoe.
        // But we can also think of it as: we want to minimize the number of shoes that change position.
        // A shoe "changes position" if it is moved to a different cell.
